import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { validateMetricRegistry } from "../src/metric-registry.ts";

const here = dirname(fileURLToPath(import.meta.url));
const registryPath = resolve(here, "../../../specs/metrics.v0.json");
const frozenRegistry = () => JSON.parse(readFileSync(registryPath, "utf8"));

const assertRejected = (label: string, tamper: (registry: any) => void) => {
  const registry = frozenRegistry();
  tamper(registry);
  const result = validateMetricRegistry(registry);
  assert.equal(result.ok, false, `${label} was accepted: ${result.errors.join("; ")}`);
};

test("metric-registry-envelope accepts the unchanged frozen registry", () => {
  const result = validateMetricRegistry(frozenRegistry());
  assert.equal(result.ok, true, result.errors.join("; "));
});

for (const [label, tamper] of [
  ["a missing registry identity", (registry: any) => { delete registry.registry_id; }],
  ["a changed registry identity", (registry: any) => { registry.registry_id = "metrics.v1"; }],
  ["missing source provenance", (registry: any) => { delete registry.source_contract; }],
  ["changed source provenance", (registry: any) => { registry.source_contract = "docs/contracts/other.md"; }],
  ["an added consumer", (registry: any) => { registry.consumers.push("factor.F7"); }],
  ["a duplicate consumer", (registry: any) => { registry.consumers.push("factor.F1"); }],
  ["a non-string consumer", (registry: any) => { registry.consumers.push(7); }],
  ["a missing canonical consumer", (registry: any) => {
    registry.consumers = registry.consumers.filter((consumer: unknown) => consumer !== "factor.F1");
  }]
] as const) {
  test(`metric-registry-envelope rejects ${label}`, () => {
    assertRejected(label, tamper);
  });
}
